package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity@Table(name="spms_objective_version",uniqueConstraints=@UniqueConstraint(name="uk_spms_objective_version",columnNames={"agency_id","objective_id","definition_version"}))
public class PerformanceObjectiveVersion extends RspAuditedEntity{
 public enum Level{AGENCY,AREA,BUSINESS_UNIT}public enum Status{DRAFT,PUBLISHED,RETIRED}
 @Column(name="objective_id",nullable=false,length=36)private String objectiveId;@Column(name="definition_version",nullable=false)private int definitionVersion;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(nullable=false,length=200)private String title;@Column(name="objective_statement",nullable=false,length=2000)private String objectiveStatement;@Column(name="expected_outcome",nullable=false,length=2000)private String expectedOutcome;@Column(name="strategy_reference",nullable=false,length=1000)private String strategyReference;@Enumerated(EnumType.STRING)@Column(name="objective_level",nullable=false,length=30)private Level level;@Column(name="organization_id")private Long organizationId;@Column(name="organization_code",length=80)private String organizationCode;@Column(name="organization_name",length=200)private String organizationName;@Column(name="parent_area_id")private Long parentAreaId;@Column(name="parent_objective_version_id",length=36)private String parentObjectiveVersionId;@Column(name="policy_version_id",nullable=false,length=36)private String policyVersionId;@Column(name="indicator_version_id",length=36)private String indicatorVersionId;@Column(name="target_value",precision=19,scale=6)private BigDecimal targetValue;@Column(name="target_from",precision=19,scale=6)private BigDecimal targetFrom;@Column(name="target_to",precision=19,scale=6)private BigDecimal targetTo;@Column(name="unit_of_measure",length=100)private String unitOfMeasure;@Column(name="source_fingerprint",length=64)private String sourceFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="effective_from")private LocalDate effectiveFrom;@Column(name="effective_to")private LocalDate effectiveTo;@Column(name="published_by",length=100)private String publishedBy;@Column(name="published_at")private Instant publishedAt;@Column(name="retired_by",length=100)private String retiredBy;@Column(name="retired_at")private Instant retiredAt;@Column(name="retirement_reason",length=1000)private String retirementReason;
 protected PerformanceObjectiveVersion(){}public PerformanceObjectiveVersion(String a,String root,int n,String prior,String title,String statement,String outcome,String reference,Level level,Long orgId,String orgCode,String orgName,Long areaId,String parent,String policy,String indicator,BigDecimal value,BigDecimal from,BigDecimal to,String unit,String source){super(a);objectiveId=requiredText(root,"objectiveId");if(n<1)throw new IllegalArgumentException("definitionVersion must be positive");definitionVersion=n;supersedesId=optionalText(prior);status=Status.DRAFT;apply(title,statement,outcome,reference,level,orgId,orgCode,orgName,areaId,parent,policy,indicator,value,from,to,unit,source);}
 public void update(String title,String statement,String outcome,String reference,Level level,Long orgId,String orgCode,String orgName,Long areaId,String parent,String policy,String indicator,BigDecimal value,BigDecimal from,BigDecimal to,String unit,String source){draft();apply(title,statement,outcome,reference,level,orgId,orgCode,orgName,areaId,parent,policy,indicator,value,from,to,unit,source);}
 private void apply(String title,String statement,String outcome,String reference,Level level,Long orgId,String orgCode,String orgName,Long areaId,String parent,String policy,String indicator,BigDecimal value,BigDecimal from,BigDecimal to,String unit,String source){this.title=requiredText(title,"title");objectiveStatement=requiredText(statement,"objectiveStatement");expectedOutcome=requiredText(outcome,"expectedOutcome");strategyReference=requiredText(reference,"strategyReference");this.level=Objects.requireNonNull(level,"level");organizationId=orgId;organizationCode=optionalText(orgCode);organizationName=optionalText(orgName);parentAreaId=areaId;parentObjectiveVersionId=optionalText(parent);policyVersionId=requiredText(policy,"policyVersionId");indicatorVersionId=optionalText(indicator);targetValue=value;targetFrom=from;targetTo=to;unitOfMeasure=optionalText(unit);sourceFingerprint=optionalText(source);if(level==Level.AGENCY&&(orgId!=null||sourceFingerprint!=null))throw new IllegalArgumentException("Agency objectives cannot reference an organization target");if(level!=Level.AGENCY&&(orgId==null||orgId<1||organizationName==null||sourceFingerprint==null))throw new IllegalArgumentException("Area and Business Unit objectives require an organization snapshot");if(from!=null&&to!=null&&to.compareTo(from)<0)throw new IllegalArgumentException("targetTo cannot be below targetFrom");}
 public void publish(LocalDate from,LocalDate to,String actor,Instant at){draft();if(from==null)throw new IllegalArgumentException("effectiveFrom is required");if(to!=null&&to.isBefore(from))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");effectiveFrom=from;effectiveTo=to;publishedBy=requiredText(actor,"actor");publishedAt=Objects.requireNonNull(at);status=Status.PUBLISHED;}public void supersede(LocalDate next,String actor,Instant at){if(status!=Status.PUBLISHED)throw new IllegalLifecycleTransitionException("Only a published objective can be superseded");effectiveTo=next.minusDays(1);retiredBy=requiredText(actor,"actor");retiredAt=at;retirementReason="Superseded";status=Status.RETIRED;}public void retire(String actor,String reason,Instant at){if(status!=Status.PUBLISHED)throw new IllegalLifecycleTransitionException("Only a published objective can be retired");retiredBy=requiredText(actor,"actor");retirementReason=requiredText(reason,"reason");retiredAt=at;status=Status.RETIRED;}private void draft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a draft objective may be edited or published");}
 public String getObjectiveId(){return objectiveId;}public int getDefinitionVersion(){return definitionVersion;}public String getSupersedesId(){return supersedesId;}public String getTitle(){return title;}public String getObjectiveStatement(){return objectiveStatement;}public String getExpectedOutcome(){return expectedOutcome;}public String getStrategyReference(){return strategyReference;}public Level getLevel(){return level;}public Long getOrganizationId(){return organizationId;}public String getOrganizationCode(){return organizationCode;}public String getOrganizationName(){return organizationName;}public Long getParentAreaId(){return parentAreaId;}public String getParentObjectiveVersionId(){return parentObjectiveVersionId;}public String getPolicyVersionId(){return policyVersionId;}public String getIndicatorVersionId(){return indicatorVersionId;}public BigDecimal getTargetValue(){return targetValue;}public BigDecimal getTargetFrom(){return targetFrom;}public BigDecimal getTargetTo(){return targetTo;}public String getUnitOfMeasure(){return unitOfMeasure;}public String getSourceFingerprint(){return sourceFingerprint;}public Status getStatus(){return status;}public LocalDate getEffectiveFrom(){return effectiveFrom;}public LocalDate getEffectiveTo(){return effectiveTo;}
}
